def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    heights = sorted(set(a))
    rank = {height: i + 1 for i, height in enumerate(heights)}
    ranks = [rank[height] for height in a]
    m = len(heights)
    tree = [0] * (m + 1)
    result = []

    for i, r in enumerate(ranks):
        if i > k:
            pos = ranks[i - k - 1]
            while pos <= m:
                tree[pos] -= 1
                pos += pos & -pos

        not_taller = 0
        pos = r
        while pos:
            not_taller += tree[pos]
            pos -= pos & -pos

        result.append(min(i, k) - not_taller)

        pos = r
        while pos <= m:
            tree[pos] += 1
            pos += pos & -pos

    return result
